package com.gymflow.inventory;import java.util.UUID;public record StockBalanceResponse(UUID productId,String sku,String productName,int quantity,int minimumStock,boolean lowStock){static StockBalanceResponse from(StockBalance s){return new StockBalanceResponse(s.getProduct().getId(),s.getProduct().getSku(),s.getProduct().getName(),s.getQuantity(),s.getProduct().getMinimumStock(),s.getQuantity()<=s.getProduct().getMinimumStock());}}
